template <std::size_t N>
inline void Decode(const std::array<wchar_t, N>& a, wchar_t* destination) {
  for (std::size_t i = 0; i < N; ++i)
    destination[i] = static_cast<wchar_t>(static_cast<unsigned>(a[i]) ^ (kLabelKey + i));
}
